# Windows toast notification actions for DSH approvals.
# Invoked by the dshnotify:// protocol handler registered by index.js.
#
# The URI is untrusted input: validate every field strictly before making any
# network request. The decision endpoint only ever listens on 127.0.0.1, and
# the token/rid are one-time values generated by the plugin for one approval.

param([string]$Uri)

if (-not $Uri) { exit 1 }

try {
    if ($Uri.Length -gt 2048) { exit 1 }
    $u = [Uri]$Uri
    if ($u.Scheme -ne 'dshnotify') { exit 1 }

    $pairs = @{}
    foreach ($item in ($u.Query.TrimStart('?') -split '&')) {
        if (-not $item) { continue }
        $kv = $item -split '=', 2
        if ($kv.Count -eq 2) {
            $pairs[[Uri]::UnescapeDataString($kv[0])] = [Uri]::UnescapeDataString($kv[1])
        }
    }

    $port = $pairs['port']
    $rid = $pairs['rid']
    $token = $pairs['token']
    $choice = $pairs['choice']

    # Strict shapes only: loopback port, 16 hex chars rid, 32 hex chars token,
    # and one of the two decision words. Anything else exits without networking.
    if ($port -notmatch '^[0-9]{1,5}$') { exit 2 }
    $portNumber = [int]$port
    if ($portNumber -lt 1 -or $portNumber -gt 65535) { exit 2 }
    if ($rid -notmatch '^[0-9a-f]{16}$') { exit 2 }
    if ($token -notmatch '^[0-9a-f]{32}$') { exit 2 }
    if ($choice -ne 'allow' -and $choice -ne 'deny') { exit 2 }

    $url = 'http://127.0.0.1:' + $portNumber + '/decision?rid=' + [Uri]::EscapeDataString($rid) +
        '&token=' + [Uri]::EscapeDataString($token) + '&choice=' + [Uri]::EscapeDataString($choice)

    Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 10 | Out-Null
} catch {
    # Best effort: a failure leaves the in-app dialog as the fallback.
    exit 3
}
